<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, setToken } from './api'

type Role = 'ADMIN' | 'MANAGER' | 'TECHNICIAN'
type User = { id:number; email:string; name:string; role:Role }
type Asset = { id:number; assetTag:string; name:string; location:string; serialNumber:string; manufacturer:string; model:string; specifications:string; status:string; uptimePercent:number; temperatureC:number; vibrationMmS:number }
type WorkOrder = { id:number; title:string; description:string; asset:Asset; assignee?:User; status:string; priority:string; dueDate:string; createdAt:string }
type Schedule = { id:number; title:string; asset:Asset; intervalDays:number; nextDueDate:string; instructions:string; active:boolean }
type Alert = { id:number; type:string; title:string; message:string; asset?:Asset; read:boolean; createdAt:string }
type Audit = { id:number; actor:string; action:string; entityType:string; entityId:number; details:string; createdAt:string }
type Reading = { id:number; asset:Asset; temperatureC:number; vibrationMmS:number; recordedAt:string }
type Dashboard = { assetCount:number; operationalCount:number; attentionCount:number; openWorkOrders:number; overdueWorkOrders:number; unreadAlerts:number; uptime:number; recentOrders:WorkOrder[]; assets:Asset[] }

const user = ref<User|null>(null), page = ref('Overview'), loading = ref(false), error = ref(''), toast = ref(''), modal = ref('')
const assetSearch = ref('')
const dashboard = ref<Dashboard|null>(null), assets = ref<Asset[]>([]), orders = ref<WorkOrder[]>([]), schedules = ref<Schedule[]>([]), alerts = ref<Alert[]>([]), audit = ref<Audit[]>([]), readings = ref<Reading[]>([]), users = ref<User[]>([])
const login = reactive({ email:'admin@plantops.local', password:'PlantOps123!' })
const assetForm = reactive({ assetTag:'', name:'', location:'Production · Line A', serialNumber:'', manufacturer:'', model:'', specifications:'', status:'Operational', uptimePercent:99, temperatureC:25, vibrationMmS:1 })
const orderForm = reactive({ title:'', description:'', assetId:0, assigneeId:0, priority:'MEDIUM', dueDate:'' })
const scheduleForm = reactive({ title:'', assetId:0, intervalDays:30, nextDueDate:'', instructions:'' })
const readingForm = reactive({ assetId:0, temperatureC:25, vibrationMmS:1 })
const nav = [{name:'Overview',icon:'◫'}, {name:'Assets',icon:'▤'}, {name:'Work orders',icon:'↗'}, {name:'Schedules',icon:'◷'}, {name:'Health',icon:'⌁'}, {name:'Alerts',icon:'♧'}, {name:'Audit log',icon:'≋'}]
const canManage = computed(() => user.value?.role !== 'TECHNICIAN')
const visibleNav = computed(() => nav.filter(item => item.name !== 'Audit log' || canManage.value))
const filteredAssets = computed(() => assets.value.filter(a => `${a.name} ${a.assetTag} ${a.location} ${a.manufacturer} ${a.model} ${a.serialNumber}`.toLowerCase().includes(assetSearch.value.toLowerCase())))
const unread = computed(() => alerts.value.filter(a => !a.read).length)
const initials = computed(() => user.value?.name.split(' ').map(x => x[0]).join('').slice(0,2) || 'PO')
const greeting = computed(() => new Date().getHours() < 12 ? 'Good morning' : new Date().getHours() < 17 ? 'Good afternoon' : 'Good evening')
const todayLabel = new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()

async function loadData() {
  if (!user.value) return
  loading.value = true; error.value=''
  try {
    const [d,a,w,s,al,r,u] = await Promise.all([api<Dashboard>('/dashboard'),api<Asset[]>('/assets'),api<WorkOrder[]>('/work-orders'),api<Schedule[]>('/schedules'),api<Alert[]>('/alerts'),api<Reading[]>('/readings'),api<User[]>('/users').catch(()=>[] as User[])])
    dashboard.value=d; assets.value=a; orders.value=w; schedules.value=s; alerts.value=al; readings.value=r; users.value=u
    if (user.value.role !== 'TECHNICIAN') audit.value=await api<Audit[]>('/audit').catch(()=>[])
  } catch (e) { error.value=(e as Error).message; if (error.value.toLowerCase().includes('unauthorized')) signOut() }
  finally { loading.value=false }
}
async function signIn(){ loading.value=true;error.value='';try{const res=await api<{token:string;user:User}>('/auth/login',{method:'POST',body:JSON.stringify(login)});setToken(res.token);user.value=res.user;await loadData()}catch(e){error.value=(e as Error).message}finally{loading.value=false} }
function signOut(){setToken('');user.value=null;page.value='Overview'}
async function act(fn:()=>Promise<unknown>,message:string){try{await fn();toast.value=message;setTimeout(()=>toast.value='',2800);modal.value='';await loadData()}catch(e){error.value=(e as Error).message}}
async function createAsset(){await act(()=>api('/assets',{method:'POST',body:JSON.stringify(assetForm)}),'Asset added');Object.assign(assetForm,{assetTag:'',name:'',serialNumber:'',manufacturer:'',model:'',specifications:'',status:'Operational',uptimePercent:99,temperatureC:25,vibrationMmS:1})}
async function createOrder(){await act(()=>api('/work-orders',{method:'POST',body:JSON.stringify({...orderForm,assigneeId:orderForm.assigneeId||null,assetId:Number(orderForm.assetId)})}),'Work order created')}
async function createSchedule(){await act(()=>api('/schedules',{method:'POST',body:JSON.stringify({...scheduleForm,assetId:Number(scheduleForm.assetId),active:true})}),'Schedule created')}
async function createReading(){await act(()=>api('/readings',{method:'POST',body:JSON.stringify({...readingForm,assetId:Number(readingForm.assetId)})}),'Reading recorded')}
async function status(order:WorkOrder,next:string){await act(()=>api(`/work-orders/${order.id}/status`,{method:'PATCH',body:JSON.stringify({status:next})}),`Work order ${next.toLowerCase().replace('_',' ')}`)}
async function assignOrder(order:WorkOrder,assigneeId:string){if(!assigneeId)return;await act(()=>api(`/work-orders/${order.id}/assign/${assigneeId}`,{method:'PATCH'}),'Technician assigned')}
async function markRead(alert:Alert){await act(()=>api(`/alerts/${alert.id}/read`,{method:'PATCH'}),'Alert marked as read')}
async function markAll(){await act(()=>api('/alerts/read-all',{method:'PATCH'}),'All alerts marked as read')}
function showCreate(kind:string){modal.value=kind;if(kind==='order'){orderForm.assetId=assets.value[0]?.id||0;orderForm.assigneeId=users.value.find(u=>u.role==='TECHNICIAN')?.id||0}if(kind==='schedule'){scheduleForm.assetId=assets.value[0]?.id||0;scheduleForm.nextDueDate=new Date(Date.now()+86400000*7).toISOString().slice(0,10)}if(kind==='reading'){readingForm.assetId=assets.value[0]?.id||0;const a=assets.value.find(x=>x.id===readingForm.assetId);readingForm.temperatureC=a?.temperatureC||25;readingForm.vibrationMmS=a?.vibrationMmS||1}}
function date(value?:string){return value?new Date(`${value.slice(0,10)}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric',year:value.length>10?'numeric':undefined}):'—'}
function time(value?:string){return value?new Date(value).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—'}
function statusClass(value:string){return value.toLowerCase().replace('_','-')}
function iconFor(type:string){return type==='ABNORMAL_READING'?'⌁':type==='MAINTENANCE_OVERDUE'?'◷':'↗'}
let timer:number|undefined
onMounted(async()=>{if(localStorage.getItem('plantops-token')){try{user.value=await api<User>('/auth/me');await loadData()}catch{signOut()}}timer=window.setInterval(()=>{if(user.value)loadData()},22000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>

<template>
  <main v-if="!user" class="login-page">
    <div class="login-card">
      <div class="brand-mark large"><span class="brand-glyph">P</span></div>
      <div class="eyebrow">INDUSTRIAL OPERATIONS</div><h1>PlantOps</h1><p class="login-sub">The health of your plant, at a glance.</p>
      <form @submit.prevent="signIn"><label>Email address</label><input v-model="login.email" type="email" required autocomplete="username"/><label>Password</label><input v-model="login.password" type="password" required autocomplete="current-password"/><p v-if="error" class="form-error">{{ error }}</p><button class="btn primary wide" :disabled="loading">{{ loading?'Signing in…':'Sign in to workspace' }} <span>→</span></button></form>
      <div class="demo-login"><span>DEMO ACCOUNTS</span><button @click="login.email='admin@plantops.local'">Admin</button><button @click="login.email='manager@plantops.local'">Manager</button><button @click="login.email='tech@plantops.local'">Technician</button><small>Password: PlantOps123!</small></div>
    </div><div class="login-foot">PLANTOPS · RELIABILITY OPERATIONS</div>
  </main>
  <div v-else class="shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark"><span class="brand-glyph">P</span></div><div><b>plantops</b><small>INDUSTRIAL OS</small></div></div>
      <div class="plant-switch"><div class="plant-icon">⌂</div><div><b>Northstar Works</b><small>Manufacturing plant</small></div><span class="chevron">⌄</span></div>
      <div class="nav-label">WORKSPACE</div>
      <nav><button v-for="item in visibleNav" :key="item.name" :class="['nav-item',{selected:page===item.name}]" @click="page=item.name"><span class="nav-icon">{{ item.icon }}</span><span>{{ item.name }}</span><span v-if="item.name==='Alerts'&&unread" class="nav-count">{{ unread }}</span></button></nav>
      <div class="sidebar-bottom"><div class="live-status"><i></i><span>All systems operational</span></div><div class="profile"><div class="avatar">{{ initials }}</div><div class="profile-copy"><b>{{ user.name }}</b><small>{{ user.role==='ADMIN'?'Administrator':user.role==='MANAGER'?'Maintenance manager':'Technician' }}</small></div><button class="icon-button logout" title="Sign out" @click="signOut">↪</button></div></div>
    </aside>
    <section class="main-area">
      <header class="topbar"><div class="crumb">Northstar Works <span>/</span> <b>{{ page }}</b></div><div class="top-actions"><div class="feed-pill"><i></i> Live feed <span class="feed-dot"></span></div><button class="icon-button top-alert" @click="page='Alerts'" title="Alerts">♧<em v-if="unread"></em></button><div class="top-avatar">{{ initials }}</div></div></header>
      <div class="content">
        <div v-if="error" class="error-banner"><span>Could not refresh data: {{ error }}</span><button @click="error='';loadData()">Retry</button></div>
        <template v-if="page==='Overview'">
          <div class="page-heading"><div><div class="eyebrow">{{ todayLabel }} <span class="live-line"></span> LIVE</div><h1>{{ greeting }}, {{ user.name.split(' ')[0] }} <span class="wave">✳</span></h1><p>Here's what's happening across your plant today.</p></div><button v-if="canManage" class="btn primary" @click="showCreate('order')"><span class="plus">+</span> New work order</button></div>
          <div v-if="loading&&!dashboard" class="loading-card">Loading plant operations…</div>
          <template v-if="dashboard">
            <div class="metrics-grid">
              <article class="metric-card"><div class="metric-top"><span>Total assets</span><span class="metric-icon blue">▤</span></div><div class="metric-value">{{ dashboard.assetCount }}<small> assets</small></div><div class="metric-foot"><span class="mini-dot green"></span>{{ dashboard.operationalCount }} operational <span class="divider">·</span>{{ dashboard.attentionCount }} need attention</div></article>
              <article class="metric-card"><div class="metric-top"><span>Open work orders</span><span class="metric-icon purple">↗</span></div><div class="metric-value">{{ dashboard.openWorkOrders }}<small> active</small></div><div class="metric-foot"><span class="mini-dot amber"></span>{{ dashboard.overdueWorkOrders }} past due date</div></article>
              <article class="metric-card"><div class="metric-top"><span>Plant uptime</span><span class="metric-icon mint">⌁</span></div><div class="metric-value">{{ dashboard.uptime }}<small>%</small></div><div class="metric-foot"><span class="trend">↗ 1.2%</span> vs. last 30 days</div></article>
              <article class="metric-card"><div class="metric-top"><span>Unread alerts</span><span class="metric-icon orange">♧</span></div><div class="metric-value">{{ dashboard.unreadAlerts }}<small> alerts</small></div><div class="metric-foot"><button class="text-link" @click="page='Alerts'">Review alerts <span>→</span></button></div></article>
            </div>
            <div class="overview-grid">
              <section class="panel asset-panel"><div class="panel-heading"><div><h2>Asset health</h2><p>Live condition across your critical equipment</p></div><button class="text-link" @click="page='Health'">View all <span>→</span></button></div><div class="health-list"><div v-for="a in assets.slice(0,4)" :key="a.id" class="health-row"><div class="equipment-icon" :class="statusClass(a.status)">{{ a.name.toLowerCase().includes('pump')?'◉':a.name.toLowerCase().includes('cnc')?'▦':a.name.toLowerCase().includes('compressor')?'◌':'▤' }}</div><div class="equipment-info"><b>{{ a.name }}</b><small>{{ a.assetTag }} <span>·</span> {{ a.location }}</small></div><div class="reading"><small>TEMP</small><b>{{ a.temperatureC }}° <i :class="a.temperatureC>=80?'bad':''"></i></b></div><div class="reading"><small>VIBRATION</small><b>{{ a.vibrationMmS }} <small>mm/s</small></b></div><span class="badge" :class="statusClass(a.status)">{{ a.status }}</span></div></div></section>
              <section class="panel alerts-panel"><div class="panel-heading"><div><h2>Recent alerts</h2><p>Signals that need your attention</p></div><button class="small-action" @click="page='Alerts'">{{ unread }} new</button></div><div class="alert-preview-list"><div v-for="a in alerts.slice(0,4)" :key="a.id" class="alert-preview"><div class="alert-symbol" :class="statusClass(a.type)">{{ iconFor(a.type) }}</div><div class="alert-copy"><b>{{ a.title }}</b><p>{{ a.message }}</p><small>{{ time(a.createdAt) }}</small></div><i v-if="!a.read" class="unread-dot"></i></div><div v-if="!alerts.length" class="empty-mini">No alerts. You're all caught up.</div></div></section>
              <section class="panel work-panel"><div class="panel-heading"><div><h2>Work orders</h2><p>Keep maintenance moving</p></div><button class="text-link" @click="page='Work orders'">All work orders <span>→</span></button></div><div class="table-wrap"><table><thead><tr><th>WORK ORDER</th><th>ASSET</th><th>ASSIGNEE</th><th>PRIORITY</th><th>STATUS</th></tr></thead><tbody><tr v-for="w in dashboard.recentOrders" :key="w.id"><td><b>#WO-{{ String(w.id).padStart(4,'0') }}</b><small>{{ w.title }}</small></td><td>{{ w.asset.assetTag }}</td><td>{{ w.assignee?.name||'Unassigned' }}</td><td><span class="priority" :class="statusClass(w.priority)"><i></i>{{ w.priority }}</span></td><td><span class="badge" :class="statusClass(w.status)">{{ w.status.replace('_',' ') }}</span></td></tr></tbody></table></div></section>
              <section class="panel reliability-panel"><div class="panel-heading"><div><h2>Reliability snapshot</h2><p>Asset availability · last 7 days</p></div><span class="period-tag">7 days⌄</span></div><div class="reliability-number">{{ dashboard.uptime }}<small>%</small><span class="trend">↗ 1.2%</span></div><div class="chart-bars"><div v-for="(v,i) in [66,77,72,89,82,94,87]" :key="i" class="bar-column"><div class="bar" :style="{height:`${v}%`}"></div><small>{{ ['F','S','S','M','T','W','T'][i] }}</small></div></div><div class="chart-legend"><span><i class="mini-dot green"></i>Availability</span><span>Target 98%</span></div></section>
            </div>
          </template>
        </template>
        <template v-else>
          <div class="page-heading"><div><div class="eyebrow">NORTHSTAR WORKS <span class="live-line"></span> OPERATIONS</div><h1>{{ page }}</h1><p>{{ page==='Assets'?'Equipment registry and condition at a glance':page==='Work orders'?'Assign, prioritize, and track maintenance work':page==='Schedules'?'Recurring inspections and preventive maintenance':page==='Health'?'Live readings and equipment condition':page==='Alerts'?'Plant signals and maintenance notifications':'A record of changes across your workspace' }}</p></div><button v-if="canManage&&['Assets','Work orders','Schedules'].includes(page)" class="btn primary" @click="showCreate(page==='Assets'?'asset':page==='Schedules'?'schedule':'order')"><span class="plus">+</span> {{ page==='Assets'?'Add asset':page==='Schedules'?'New schedule':'New work order' }}</button></div>
          <section v-if="page==='Assets'" class="panel full-panel"><div class="panel-heading"><div><h2>Asset registry</h2><p>{{ assets.length }} registered machines · Northstar Works</p></div><input v-model="assetSearch" class="search-input" placeholder="⌕  Search assets"/></div><div class="table-wrap"><table class="wide-table"><thead><tr><th>ASSET</th><th>LOCATION</th><th>MANUFACTURER / MODEL</th><th>SERIAL NO.</th><th>UPTIME</th><th>CONDITION</th></tr></thead><tbody><tr v-for="a in filteredAssets" :key="a.id"><td><div class="cell-main"><span class="equipment-icon">▤</span><div><b>{{ a.name }}</b><small>{{ a.assetTag }}</small></div></div></td><td>{{ a.location }}</td><td>{{ a.manufacturer }} <small class="subline">{{ a.model }}</small></td><td>{{ a.serialNumber }}</td><td><b>{{ a.uptimePercent }}%</b></td><td><span class="badge" :class="statusClass(a.status)"><i class="status-pip"></i>{{ a.status }}</span></td></tr></tbody></table></div></section>
          <section v-else-if="page==='Work orders'" class="panel full-panel"><div class="panel-heading"><div><h2>Maintenance queue</h2><p>{{ orders.length }} total work orders</p></div><div class="filter-tag">All statuses⌄</div></div><div class="table-wrap"><table class="wide-table"><thead><tr><th>WORK ORDER</th><th>ASSET</th><th>ASSIGNEE</th><th>DUE DATE</th><th>PRIORITY</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody><tr v-for="w in orders" :key="w.id"><td><b>#WO-{{ String(w.id).padStart(4,'0') }}</b><small class="subline">{{ w.title }}</small></td><td>{{ w.asset.name }}</td><td><select v-if="canManage" class="status-select" :value="w.assignee?.id||0" @change="assignOrder(w,($event.target as HTMLSelectElement).value)"><option v-if="!w.assignee" :value="0">Unassigned</option><option v-for="u in users.filter(x=>x.role==='TECHNICIAN')" :key="u.id" :value="u.id">{{ u.name }}</option></select><span v-else>{{ w.assignee?.name||'Unassigned' }}</span></td><td>{{ date(w.dueDate) }}</td><td><span class="priority" :class="statusClass(w.priority)"><i></i>{{ w.priority }}</span></td><td><span class="badge" :class="statusClass(w.status)">{{ w.status.replace('_',' ') }}</span></td><td><select v-if="w.status!=='COMPLETED'&&w.status!=='CANCELLED'" class="status-select" :value="w.status" @change="status(w,($event.target as HTMLSelectElement).value)"><option v-if="canManage" value="OPEN">Open</option><option v-if="canManage&&w.assignee" value="ASSIGNED">Assigned</option><option value="IN_PROGRESS">In progress</option><option value="COMPLETED">Completed</option><option v-if="canManage" value="CANCELLED">Cancelled</option></select><span v-else class="muted">—</span></td></tr></tbody></table></div></section>
          <section v-else-if="page==='Schedules'" class="schedule-grid"><article v-for="s in schedules" :key="s.id" class="panel schedule-card"><div class="schedule-top"><div class="schedule-icon">◷</div><span class="badge" :class="s.active?'operational':'cancelled'">{{ s.active?'Active':'Paused' }}</span></div><h2>{{ s.title }}</h2><p>{{ s.asset.name }} <span>·</span> {{ s.asset.assetTag }}</p><div class="schedule-rule"><span>REPEAT EVERY</span><b>{{ s.intervalDays }} days</b></div><div class="schedule-rule"><span>NEXT DUE</span><b>{{ date(s.nextDueDate) }}</b></div><div class="schedule-note">{{ s.instructions }}</div></article><div v-if="!schedules.length" class="panel empty-state">No maintenance schedules yet.</div></section>
          <section v-else-if="page==='Health'" class="panel full-panel"><div class="panel-heading"><div><h2>Equipment telemetry</h2><p>Simulated live feed · updates every 20 seconds</p></div><button class="btn primary" @click="showCreate('reading')">＋ Record reading</button></div><div class="table-wrap"><table class="wide-table"><thead><tr><th>EQUIPMENT</th><th>TEMPERATURE</th><th>VIBRATION</th><th>UPTIME</th><th>HEALTH</th></tr></thead><tbody><tr v-for="a in assets" :key="a.id"><td><div class="cell-main"><span class="equipment-icon">⌁</span><div><b>{{ a.name }}</b><small>{{ a.assetTag }}</small></div></div></td><td><b :class="a.temperatureC>=80?'critical-text':''">{{ a.temperatureC }} °C</b><div class="meter"><i :style="{width:`${Math.min(a.temperatureC,100)}%`}" :class="a.temperatureC>=80?'meter-warn':''"></i></div></td><td><b :class="a.vibrationMmS>=4.5?'critical-text':''">{{ a.vibrationMmS }} mm/s</b><div class="meter"><i :style="{width:`${Math.min(a.vibrationMmS*18,100)}%`}" :class="a.vibrationMmS>=4.5?'meter-warn':''"></i></div></td><td>{{ a.uptimePercent }}%</td><td><span class="badge" :class="statusClass(a.status)">{{ a.status }}</span></td></tr></tbody></table></div><div class="health-footnote">Thresholds: temperature ≥ 80 °C · vibration ≥ 4.5 mm/s</div></section>
          <section v-else-if="page==='Alerts'" class="panel full-panel"><div class="panel-heading"><div><h2>Alert inbox</h2><p>{{ unread }} unread signals · generated from health and maintenance events</p></div><button class="text-link" v-if="unread" @click="markAll">Mark all as read</button></div><div class="inbox-list"><article v-for="a in alerts" :key="a.id" class="inbox-row" :class="{unread:!a.read}"><div class="alert-symbol" :class="statusClass(a.type)">{{ iconFor(a.type) }}</div><div class="inbox-copy"><div><b>{{ a.title }}</b><span class="badge" :class="statusClass(a.type)">{{ a.type.replaceAll('_',' ') }}</span></div><p>{{ a.message }}</p><small>{{ a.asset?.assetTag||'Plant system' }} · {{ time(a.createdAt) }}</small></div><button v-if="!a.read" class="text-link" @click="markRead(a)">Mark read</button><span v-else class="read-label">Read</span></article><div v-if="!alerts.length" class="empty-state">No alerts in your inbox.</div></div></section>
          <section v-else-if="page==='Audit log'" class="panel full-panel"><div class="panel-heading"><div><h2>Activity history</h2><p>Recent changes made across PlantOps</p></div><span class="filter-tag">Latest first</span></div><div class="table-wrap"><table class="wide-table"><thead><tr><th>ACTOR</th><th>ACTIVITY</th><th>RECORD</th><th>DETAILS</th><th>TIME</th></tr></thead><tbody><tr v-for="item in audit" :key="item.id"><td><div class="actor-cell"><span class="avatar tiny">{{ item.actor.slice(0,1).toUpperCase() }}</span>{{ item.actor }}</div></td><td><span class="action-label">{{ item.action.replaceAll('_',' ') }}</span></td><td>{{ item.entityType }} <small>#{{ item.entityId }}</small></td><td>{{ item.details }}</td><td>{{ time(item.createdAt) }}</td></tr></tbody></table><div v-if="!audit.length" class="empty-state">No activity has been recorded yet.</div></div></section>
        </template>
        <div class="footer-line"><span>PLANTOPS <i>·</i> NORTHSTAR WORKS</span><span>LAST SYNC {{ new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}) }} <i class="mini-dot green"></i></span></div>
      </div>
    </section>
    <div v-if="modal" class="modal-backdrop" @click.self="modal=''"><form v-if="modal==='asset'" class="modal-card" @submit.prevent="createAsset"><div class="modal-top"><div><div class="eyebrow">ASSET REGISTRY</div><h2>Add an asset</h2></div><button type="button" class="icon-button" @click="modal=''">×</button></div><div class="form-grid"><div><label>Asset tag</label><input v-model="assetForm.assetTag" required placeholder="P-1042"/></div><div><label>Asset name</label><input v-model="assetForm.name" required placeholder="Cooling water pump"/></div><div class="span-2"><label>Location</label><input v-model="assetForm.location" required placeholder="Production · Line A"/></div><div><label>Manufacturer</label><input v-model="assetForm.manufacturer"/></div><div><label>Model</label><input v-model="assetForm.model"/></div><div><label>Serial number</label><input v-model="assetForm.serialNumber"/></div><div><label>Specifications</label><input v-model="assetForm.specifications" placeholder="Power · capacity"/></div></div><div class="modal-actions"><button type="button" class="btn secondary" @click="modal=''">Cancel</button><button class="btn primary" :disabled="loading">Create asset →</button></div></form>
      <form v-else-if="modal==='order'" class="modal-card" @submit.prevent="createOrder"><div class="modal-top"><div><div class="eyebrow">MAINTENANCE</div><h2>New work order</h2></div><button type="button" class="icon-button" @click="modal=''">×</button></div><div class="form-grid"><div class="span-2"><label>Work order title</label><input v-model="orderForm.title" required placeholder="Inspect pump bearings"/></div><div class="span-2"><label>Description</label><textarea v-model="orderForm.description" rows="3" placeholder="Describe the maintenance task"></textarea></div><div><label>Asset</label><select v-model="orderForm.assetId" required><option v-for="a in assets" :key="a.id" :value="a.id">{{ a.assetTag }} · {{ a.name }}</option></select></div><div><label>Assign technician</label><select v-model="orderForm.assigneeId"><option :value="0">Unassigned</option><option v-for="u in users.filter(x=>x.role==='TECHNICIAN')" :key="u.id" :value="u.id">{{ u.name }}</option></select></div><div><label>Priority</label><select v-model="orderForm.priority"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></div><div><label>Due date</label><input v-model="orderForm.dueDate" type="date"/></div></div><div class="modal-actions"><button type="button" class="btn secondary" @click="modal=''">Cancel</button><button class="btn primary" :disabled="loading">Create work order →</button></div></form>
      <form v-else-if="modal==='schedule'" class="modal-card" @submit.prevent="createSchedule"><div class="modal-top"><div><div class="eyebrow">PREVENTIVE MAINTENANCE</div><h2>New schedule</h2></div><button type="button" class="icon-button" @click="modal=''">×</button></div><div class="form-grid"><div class="span-2"><label>Schedule name</label><input v-model="scheduleForm.title" required placeholder="Monthly pump inspection"/></div><div><label>Asset</label><select v-model="scheduleForm.assetId" required><option v-for="a in assets" :key="a.id" :value="a.id">{{ a.assetTag }} · {{ a.name }}</option></select></div><div><label>Repeat every (days)</label><input v-model.number="scheduleForm.intervalDays" type="number" min="1" required/></div><div><label>Next due date</label><input v-model="scheduleForm.nextDueDate" type="date" required/></div><div class="span-2"><label>Instructions</label><textarea v-model="scheduleForm.instructions" rows="3" placeholder="Inspection steps"></textarea></div></div><div class="modal-actions"><button type="button" class="btn secondary" @click="modal=''">Cancel</button><button class="btn primary" :disabled="loading">Create schedule →</button></div></form>
      <form v-else class="modal-card" @submit.prevent="createReading"><div class="modal-top"><div><div class="eyebrow">EQUIPMENT HEALTH</div><h2>Record a reading</h2></div><button type="button" class="icon-button" @click="modal=''">×</button></div><div class="form-grid"><div class="span-2"><label>Asset</label><select v-model="readingForm.assetId" required><option v-for="a in assets" :key="a.id" :value="a.id">{{ a.assetTag }} · {{ a.name }}</option></select></div><div><label>Temperature (°C)</label><input v-model.number="readingForm.temperatureC" type="number" min="0" step="0.1" required/></div><div><label>Vibration (mm/s)</label><input v-model.number="readingForm.vibrationMmS" type="number" min="0" step="0.1" required/></div></div><div class="modal-actions"><button type="button" class="btn secondary" @click="modal=''">Cancel</button><button class="btn primary" :disabled="loading">Save reading →</button></div></form>
    </div>
    <transition name="toast"><div v-if="toast" class="toast-message"><span>✓</span>{{ toast }}</div></transition>
  </div>
</template>
